INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G002','{"program_id":"G002","title":"기후행동1.5℃ 실천기록·게임·스쿨챌린지","target":"전국 이용자; 스쿨챌린지는 해당 회차 공고의 학생·학교 대상","eligibility_logic":"A01은 사이트/앱 가입 뒤 실천기록·퀴즈·게임을 이용하는 안내형 행동이다. A02는 별도 스쿨챌린지 공고의 대상·절차를 모두 충족할 때만 참여한다.","benefit":"A01의 현금·경품은 공식 본문에서 확인하지 못했다. A02의 상·상품은 회차 공고별로 달라 현재 확정하지 않는다.","application_period":"A01 상시 이용 안내; A02 회차별 공고 확인 필요","usage_period":"A01 사이트·앱 운영 기간; A02 회차별","documents":"A01 공식 본문에서 별도 서류 미확인; A02 회차 공고 확인 필요","application_method":"공식 사이트 또는 앱에서 회원가입 후 메뉴 이용; 스쿨챌린지는 해당 공고 경로 이용","status":"운영 안내 확인","caveat":"공식 첫 화면은 2026-09-17에 실천기록·퀴즈·게임·스쿨챌린지 메뉴와 참여 가능 이벤트를 표시한다. 현재 스쿨챌린지의 모집·선정·시상 조건은 본문으로 확인하지 못했다.","action_ids":["G002-A01","G002-A02"],"sources":[{"id":"G002-S01","url":"https://c-action.kr/web/index.html","title":"기후행동1.5℃ 공식 사이트","status":"공식 본문 확인","as_of":"2026-09-17 화면","checked_at":"2026-09-17","supports":"A01 메뉴·회원가입·기록/퀴즈/게임 안내, A02 스쿨챌린지 메뉴·현재 이벤트 표시"},{"id":"G002-S02","url":"https://www.cpoint.or.kr/netzero/site/cntnts/CNTNTS_003.do","title":"탄소중립포인트 녹색생활실천 참여방법","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"미래세대실천행동은 기후행동1.5℃를 통해 참가한다는 연결 안내"}],"conditions":[{"id":"G002-C01","group":"실천기록·게임","group_logic":"안내","requirement":"회원가입 후 실천기록·퀴즈·게임 메뉴 이용","detail":"현금·경품 지급은 확인되지 않음","applies_to":"G002-A01 이용자","relation":"A02와 독립","source_ids":["G002-S01"],"verification":"공식 본문 확인"},{"id":"G002-C02","group":"스쿨챌린지","group_logic":"행동별 분기","requirement":"해당 회차의 대상·모집 절차 충족","detail":"학생·학교 대상이라는 기존 설명은 있으나 2026 회차 상세 원문 미확인","applies_to":"G002-A02","relation":"A01 이용만으로 충족되지 않음","source_ids":["G002-S01","G002-S02"],"verification":"공식 메뉴·연결 본문 확인; 상세 조건 미확인"}],"overview_source_ids":["G002-S01","G002-S02"]}'::jsonb);
