INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G003','{"program_id":"G003","title":"K-패스·모두의 카드 환급 기준 확인","target":"K-패스 참여 지자체에 주민등록된 만 19세 이상 이용자","eligibility_logic":"기존 K-패스 정률 환급은 만 19세 이상 AND 참여 지자체 주민등록 AND 월 15회 이상 대중교통 이용을 충족한다. 적용 횟수·유형별 비율과 2026 정액패스(모두의 카드)의 관계는 공식 K-패스 본문 접속 실패로 하나의 계산식으로 합치지 않는다.","benefit":"국회예산정책처가 인용한 국토교통부 자료: 기존 정률 환급은 월 최대 60회(일 2회) 20~53% 등 유형별 비율; 2026 정액패스는 유형·수단별 초과 이용금액 환급 구조. 정확한 현재 개인 적용액은 공식 K-패스에서 재확인 필요.","application_period":"상시 여부 공식 K-패스 본문 미확인","usage_period":"월별 이용 실적 기준","documents":"카드 발급·회원가입·주소 검증의 현재 서류는 공식 본문 미확인","application_method":"K-패스 지원 카드 발급 및 홈페이지/앱 회원가입·카드 등록으로 알려졌으나 2026 공식 본문 접근 실패","status":"공식 K-패스 사이트 접근 실패; 공공기관 자료로 기존·정액 방식 확인","caveat":"korea-pass.kr은 2026-09-17 웹 조회에서 502로 열리지 않았다. 정부·공공기관 이외 출처의 수치로 보완하지 않았다.","action_ids":["G003-A01"],"sources":[{"id":"G003-S01","url":"https://korea-pass.kr/","title":"K-패스 공식 홈페이지","status":"접근 실패","as_of":"미표시","checked_at":"2026-09-17","supports":"최신 신청·카드·정액패스 적용관계는 확인 불가"},{"id":"G003-S02","url":"https://nabo.go.kr/board/file/bulkDown.do?bid=19&idx=8961","title":"국회예산정책처 K-패스 사업 개요(국토교통부 자료 인용)","status":"공식 본문 확인","as_of":"2026","checked_at":"2026-09-17","supports":"만19세·참여지자체·월15회, 기존 정률 및 2026 정액패스 구분"}],"conditions":[{"id":"G003-C01","group":"기본 자격","group_logic":"모두 충족","requirement":"만 19세 이상","detail":"어린이·청소년은 해당하지 않는다고 공공기관 자료에 기재","applies_to":"G003-A01 이용자","relation":"월 이용 조건과 AND","source_ids":["G003-S02"],"verification":"공식 공공기관 본문 확인"},{"id":"G003-C02","group":"기존 정률 환급 이용","group_logic":"모두 충족","requirement":"월 15회 이상 대중교통 이용","detail":"월 최대 60회·일 최대 2회 및 유형별 비율은 기존 정률 방식 설명에 한정","applies_to":"G003-A01","relation":"정액패스에 자동 확대하지 않음","source_ids":["G003-S02"],"verification":"공식 공공기관 본문 확인"},{"id":"G003-C03","group":"2026 정액패스","group_logic":"안내","requirement":"이용수단·이용유형별 별도 기준","detail":"초과 이용금액 환급 방식으로 소개되나 공식 K-패스 세부 본문 접근 실패","applies_to":"G003-A01","relation":"C02와 계산식 합산 금지","source_ids":["G003-S01","G003-S02"],"verification":"공식 공공기관 요약 확인; 공식 운영 본문 미확인"},{"id":"G003-C04","group":"거주 지역","group_logic":"모두 충족","requirement":"K-패스 참여 지자체에 주민등록","detail":"주소 확인 기준; 현재 운영사이트 세부는 미확인","applies_to":"G003-A01 이용자","relation":"월 이용 조건과 AND","source_ids":["G003-S02"],"verification":"공식 공공기관 본문 확인"}],"overview_source_ids":["G003-S01","G003-S02"]}'::jsonb);
