INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G004','{"program_id":"G004","title":"그린카드 에코머니 녹색소비 적립","target":"그린카드로 제휴유통사의 적립대상 친환경제품을 결제하는 이용자","eligibility_logic":"제휴유통사 방문 AND 적립대상제품 확인 AND 그린카드 결제가 필요하다. 인증표지만으로는 적립이 보장되지 않으며 제품 성격·인증 유효기간·제휴처·카드사별 서비스가 분기한다.","benefit":"에코머니 포인트 적립(1포인트=1원); 녹색소비 적립률은 구매금액의 일정 비율, 최대 25%로 공식 안내되며 제휴처마다 다르다.","application_period":"제품·제휴처·카드상품별 운영","usage_period":"2026년 9월 적립대상제품 목록이 공식 사이트에 게시됨","documents":"별도 제출서류 미확인","application_method":"그린카드 발급·이용 조건을 카드사에서 확인하고 제휴유통사에서 적립대상제품을 그린카드로 결제","status":"운영 안내 및 2026년 9월 대상제품 목록 확인","caveat":"기존 입력의 최대 15%는 공식 일반 안내(최대 25%)와 다르므로 15%를 공통값으로 사용하지 않는다.","action_ids":["G004-A01"],"sources":[{"id":"G004-S01","url":"https://www.green-card.co.kr/app/greenservice/greenShopListPage.do","title":"그린카드 녹색소비","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"적립대상 정의, 인증표시 제외 가능성, 결제 절차, 최대 25%"},{"id":"G004-S02","url":"https://www.green-card.co.kr/app/ecomoney/ecoMoneyAccumulationGuidePage.do","title":"에코머니 포인트 적립 안내","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"제휴처·카드사별 차이와 1포인트=1원"},{"id":"G004-S03","url":"https://www.green-card.co.kr/app/greenservice/ecoProductListPage.do","title":"친환경제품 적립대상제품","status":"공식 본문 확인","as_of":"2026년 9월","checked_at":"2026-09-17","supports":"현재 월별 적립대상제품 목록"}],"conditions":[{"id":"G004-C01","group":"결제·제품","group_logic":"모두 충족","requirement":"그린카드 적립대상 제품 구매","detail":"결제전표에서 적립 포인트를 확인하는 절차","applies_to":"G004-A01 구매 건","relation":"카드상품 조건과 AND","source_ids":["G004-S01"],"verification":"공식 본문 확인"},{"id":"G004-C02","group":"적립 제외·변동","group_logic":"제외","requirement":"인증표시만으로 적립 확정 불가","detail":"제품 성격·인증 유효기간에 따라 제외 가능; 제휴처·카드사별 적립률·서비스 상이","applies_to":"G004-A01 구매 건","relation":"C01 충족 여부를 월별 목록·카드 약관으로 확인","source_ids":["G004-S01","G004-S02","G004-S03"],"verification":"공식 본문 확인"},{"id":"G004-C03","group":"참여 판매처","group_logic":"모두 충족","requirement":"그린카드 제휴유통사에서 구매","detail":"참여 업체·매장을 공식 목록에서 확인","applies_to":"G004-A01 구매 건","relation":"카드상품 조건과 AND","source_ids":["G004-S01"],"verification":"공식 본문 확인"},{"id":"G004-C04","group":"결제 수단","group_logic":"모두 충족","requirement":"그린카드로 결제","detail":"사용 카드의 해당 서비스 조건 적용","applies_to":"G004-A01 구매 건","relation":"카드상품 조건과 AND","source_ids":["G004-S01"],"verification":"공식 본문 확인"}],"overview_source_ids":["G004-S01","G004-S02","G004-S03"]}'::jsonb);
