INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G007','{"program_id":"G007","title":"자전거 안전교육 자료 이용","target":"공개 안전교육 자료를 이용하려는 사람","eligibility_logic":"별도 열람 자격은 공식 교육자료 페이지에서 확인되지 않았다. 자료 유형은 이용자 집단별로 나뉘지만 이용 제한은 아니다.","benefit":"초등학생·중고등학생·성인용 ‘안전한 자전거 타기’ 자료와 연령대별 안전교육 자료 열람·다운로드 안내.","application_period":"상시 공개 자료","usage_period":"해당 없음","documents":"없음","application_method":"자전거행복나눔의 자전거 안전교육 > 교육자료에서 자료 유형을 선택한다.","status":"공식 본문 확인","caveat":"국토종주 인증·대면교육·공모전 조건은 자료 이용 조건이 아니다.","action_ids":["G007-A01"],"sources":[{"id":"G007-S01","url":"https://www.bike.go.kr/content.do?key=2008148326130","title":"자전거행복나눔 교육자료","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"자료 유형과 공개 교육자료 이용 안내"}],"conditions":[{"id":"G007-C01","group":"이용 안내","group_logic":"안내","requirement":"초등학생·중고등학생·성인용 자료 중 해당 자료 선택","detail":"자료의 대상별 구분이며 별도 열람 자격으로 확인되지 않음","applies_to":"자료 이용 행동","relation":"인증·대면교육과 독립","source_ids":["G007-S01"],"verification":"공식 본문 확인"}],"overview_source_ids":["G007-S01"]}'::jsonb);
