INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G008','{"program_id":"G008","title":"서울 따릉이 자전거 대여","target":"만 13세 이상 서울 공공자전거 이용권을 구매하여 대여하려는 이용자","eligibility_logic":"만 13세 이상 AND 이용권·결제 조건 충족. 만 13세 회원은 법정대리인의 개인정보 처리 동의와 휴대폰 인증이 필요하다고 공식 FAQ·약관 개정자료가 안내한다. 과거 ‘만 14세 미만’ 동의 문구도 공식 약관 자료에 남아 있어, 14세 연령 전체에 현재 같은 절차가 적용된다고 확정하지 않는다.","benefit":"서울 공공자전거 이용권 구매 및 대여 서비스.","application_period":"상시 서비스로 안내되나 대여소·자전거·이용권별 이용 가능 상태는 별도 확인","usage_period":"이용권 조건 및 대여·반납 시점에 따름","documents":"만 13세 가입은 법정대리인 휴대폰 인증·동의 안내; 그 밖의 별도 서류 확인 안 됨","application_method":"따릉이 앱 또는 안내된 공식 이용권·결제 안내에서 가입, 연령별 동의, 이용권 및 결제 방법을 확인한다.","status":"공식 본문 확인","caveat":"현재 공식 페이지는 만 13세 이상 이용 가능과 만 13세 법정대리인 동의를 확인한다. 이전 만 14세 미만 문구는 구·개정 대비 자료이므로 현재 일반 조건으로 쓰지 않는다.","action_ids":["G008-A01"],"sources":[{"id":"G008-S01","url":"https://www.sisul.or.kr/open_content/main/bbs/bbsMsgDetail.do?bcd=faq&msg_seq=503","title":"서울시설공단 따릉이 요금 및 결제수단 FAQ","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"결제수단과 앱 내 이용권·추가요금 안내 경로"},{"id":"G008-S02","url":"https://sisul.or.kr/open_content/traffic/bikeseoul.jsp","title":"서울시설공단 공공자전거 안내","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"만 13세 이상 이용 가능 및 앱 설치·이용권 구매 안내"},{"id":"G008-S03","url":"https://www.sisul.or.kr/open_content/childrenpark/bbs/bbsMsgList.do?bcd=faq&pgno=4","title":"서울시설공단 따릉이 연령 FAQ","status":"공식 검색결과만 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"만 13세 회원의 법정대리인 휴대폰 인증"},{"id":"G008-S04","url":"https://www.bikeseoul.com/upload/TermsofUse/Comparisontable%284.23.~%29.pdf","title":"서울공공자전거 이용약관 신·구조문 대비표","status":"공식 본문 확인","as_of":"최근 개정안, 정확한 시행일 미표시","checked_at":"2026-09-17","supports":"만 13세 법정대리인 개인정보 처리 동의와 과거 만 14세 미만 문구의 구분"}],"conditions":[{"id":"G008-C01","group":"최저 연령","group_logic":"모두 충족","requirement":"만 13세 이상","detail":"서울시설공단 공공자전거 안내의 현재 이용 가능 연령","applies_to":"이용자·G008-A01","relation":"이용권·결제 및 만 13세 동의 조건과 함께 적용","source_ids":["G008-S02"],"verification":"공식 본문 확인"},{"id":"G008-C02","group":"만 13세 법정대리인 동의","group_logic":"조건부 모두 충족","requirement":"만 13세 회원가입 시 법정대리인의 개인정보 처리 동의 및 휴대폰 인증","detail":"이전 ‘만 14세 미만’ 동의 문구는 구·개정 대비 자료에 있어 현재 14세 전체 조건으로 확정하지 않음","applies_to":"만 13세 가입자","relation":"최저 연령과 이용권 조건에 추가","source_ids":["G008-S03","G008-S04"],"verification":"공식 검색결과 및 공식 본문 확인"},{"id":"G008-C03","group":"이용권·결제 안내","group_logic":"안내","requirement":"이용권과 결제수단을 공식 안내에서 확인","detail":"휴대폰 소액결제·카드·간편결제 등이 FAQ에 열거됨","applies_to":"이용권 구매·대여 행동","relation":"대여소 재고·운영 여부와 별도","source_ids":["G008-S01"],"verification":"공식 본문 확인"}],"overview_source_ids":["G008-S01","G008-S02","G008-S03","G008-S04"]}'::jsonb);
