INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G027','{"program_id":"G027","title":"민간건축물 그린리모델링 이자지원","target":"2016-01-01 이전 사용승인된 기존 민간건축물의 에너지 성능개선 민간사업","eligibility_logic":"기존건축물·미완료 공사·필수 기술요소·건물용도별 성능개선 기준을 모두 충족하고 센터 심사와 금융기관 대출심사를 통과해야 한다.","benefit":"공사비 대출약정에 4.5~5.5%p 이자 지원; 실제 적용률은 성능·우대자격·대출방식에 따라 다름.","application_period":"2026년 공고일부터 이자지원 예산 소진 시까지 선착순.","usage_period":"대출 약정·상환기간에 따라 이자지원.","documents":"사업신청 서식, 성능평가/창호 등 기준증빙, 등기·건축물대장·계약서 등; 해당 기준별 상이.","application_method":"건축주 동의를 받은 그린리모델링 사업자가 사업관리시스템에 신청하고, 사업확인 후 건축주가 금융기관 대출 조회·실행.","status":"2026 공식 본문 확인","caveat":"대출 한도·상환은 건물용도·은행·카드에 따라 달라 개별 확인 필요.","action_ids":["G027-A01"],"sources":[{"id":"G027-S01","url":"https://www.greenremodeling.or.kr/n1/support/sup1000.asp","title":"2026년 민간건축물 그린리모델링 이자지원 사업 공고문","status":"공식 본문 확인","as_of":"2026","checked_at":"2026-09-17","supports":"대상, 성능기준, 지원율, 제외·우대, 접수·서류·절차"}],"conditions":[{"id":"G027-C01","group":"건축물·공사","group_logic":"모두 충족","requirement":"2016-01-01 이전 사용승인 기존 민간건축물의 미완료 에너지 성능개선 공사","detail":"정부·지자체 지원을 받은 경우 해당 지원금 외 공사비만 가능","applies_to":"건축물·공사","relation":"성능기준·심사와 모두 충족","source_ids":["G027-S01"],"verification":"공식 본문 확인"},{"id":"G027-C02","group":"성능개선 기준","group_logic":"건물유형별 하나 충족","requirement":"주거·비주거의 20% 이상 성능개선 또는 단독주택 간이평가, 공동주택 2등급 이상 창호 등","detail":"필수 기술요소 1개 이상 포함; 용도별 기준과 증빙 상이","applies_to":"공사","relation":"C01 후 사업심사 대상","source_ids":["G027-S01"],"verification":"공식 본문 확인"},{"id":"G027-C03","group":"우대 이자지원","group_logic":"묶음 안 하나 충족","requirement":"기초생활수급자·차상위계층","detail":"신청일 기준 해당; 5.5%p 우대","applies_to":"건축주·공사","relation":"기본 대상·심사 충족 후 C03,C05~C09 중 하나이면 우대율 적용; 금융심사 C04는 대체 조건이 아님","source_ids":["G027-S01"],"verification":"공식 본문 확인"},{"id":"G027-C04","group":"심사·금융","group_logic":"모두 충족","requirement":"센터 사업확인과 금융기관 대출 가능 여부","detail":"제출 미비 또는 신용·압류 등으로 거부 가능","applies_to":"사업자·건축주","relation":"자격 충족해도 승인·대출은 별도","source_ids":["G027-S01"],"verification":"공식 본문 확인"},{"id":"G027-C05","group":"우대 이자지원","group_logic":"묶음 안 하나 충족","requirement":"신혼부부","detail":"현재 혼인 중이며 혼인 7년 이내; 5.5%p","applies_to":"건축주","relation":"기본 대상·심사 충족 후 C03,C05~C09 중 하나이면 우대율 적용; 금융심사 C04는 대체 조건이 아님","source_ids":["G027-S01"],"verification":"공식 본문 확인"},{"id":"G027-C06","group":"우대 이자지원","group_logic":"묶음 안 하나 충족","requirement":"다자녀","detail":"만 18세 이하 자녀 2명 이상; 5.5%p","applies_to":"건축주","relation":"기본 대상·심사 충족 후 C03,C05~C09 중 하나이면 우대율 적용; 금융심사 C04는 대체 조건이 아님","source_ids":["G027-S01"],"verification":"공식 본문 확인"},{"id":"G027-C07","group":"우대 이자지원","group_logic":"묶음 안 하나 충족","requirement":"고령자(65세 이상)","detail":"신청일 기준 65세 이상; 5.5%p 우대","applies_to":"건축주","relation":"기본 대상·심사 충족 후 C03,C05~C09 중 하나이면 우대율 적용; 금융심사 C04는 대체 조건이 아님","source_ids":["G027-S01"],"verification":"공식 본문 확인"},{"id":"G027-C09","group":"우대 이자지원","group_logic":"묶음 안 하나 충족","requirement":"국가유공자·해당 유족·가족","detail":"법정 국가유공 자격; 5.5%p 우대","applies_to":"건축주","relation":"기본 대상·심사 충족 후 C03,C05~C09 중 하나이면 우대율 적용; 금융심사 C04는 대체 조건이 아님","source_ids":["G027-S01"],"verification":"공식 본문 확인"},{"id":"G027-C08","group":"우대 이자지원","group_logic":"묶음 안 하나 충족","requirement":"공사 전 대비 에너지 성능개선 비율 30% 이상","detail":"우대 인적자격이 없어도 성능 기준으로 5.5%p 적용","applies_to":"건축물·공사","relation":"기본 대상·심사 충족 후 C03,C05~C09 중 하나이면 우대율 적용; 금융심사 C04는 대체 조건이 아님","source_ids":["G027-S01"],"verification":"공식 본문 확인"}],"overview_source_ids":["G027-S01"]}'::jsonb);
