INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G031','{"program_id":"G031","title":"2026 에너지바우처","target":"일반 바우처(A01): 수급자격과 세대원 특성 충족 세대. 연탄전환(A02): 2026년 이후 보일러 전환 및 취약계층 기준 충족 세대.","eligibility_logic":"A01: 수급자격 AND 세대원 특성 8유형 중 하나. A02: 연탄보일러 전환 AND 취약계층 6유형 중 하나. 각각의 시설·중복 제한을 적용하며 두 분기의 소득·세대원 요건을 합치지 않음.","benefit":"A01 연간 총액: 1/2/3/4인 이상 각각 295,200/407,500/532,700/701,300원. 다른 동절기 지원 선택 시 하절기만 각각 40,700/58,800/75,800/102,000원. A02 세대당 576,000원; 실물 국민행복카드로 전기·도시가스·등유·LPG 결제.","application_period":"A01: 2026-06-15~12-31. A02: 2026-08-03~12-31(재신청은 2027-05-31까지).","usage_period":"A01: 2026-07-01~2027-05-31; 하절기 요금차감, 동절기 요금차감10/1·실물카드10/3 시작. A02: 2026-10-03~2027-05-31.","documents":"공통: 에너지이용권 신청서; 대리 신청은 위임장·대리인 신분증. A01 요금차감은 최근 고지서. A02 보일러 설치·시공 확인 및 전환 경로별 지원결정 증빙(지자체 내부 확인 시 일부 생략).","application_method":"주소지 행정복지센터 또는 복지로. 동의하에 공무원 직권 신청 가능.","status":"A01·A02 2026 공식 본문 확인","caveat":"A02 본인부담 등 기타 전환 경로에는 2025년 이후 연탄쿠폰 수급 이력이 추가됨. 일반 바우처 동절기 중복 제한은 하절기까지 일괄 제외하는 조건이 아님.","action_ids":["G031-A01","G031-A02"],"sources":[{"id":"G031-S01","url":"https://www.energyv.or.kr/info/support_info.do","title":"에너지바우처 지원기준·기간","status":"공식 본문 확인","as_of":"2026","checked_at":"2026-09-17","supports":"A01 대상, 제외·중복, 금액, 사용기간"},{"id":"G031-S02","url":"https://www.energyv.or.kr/info/apl_info.do","title":"에너지바우처 신청안내","status":"공식 본문 확인","as_of":"2026","checked_at":"2026-09-17","supports":"A01 신청인·방법·기간·서류"},{"id":"G031-S03","url":"https://www.energyv.or.kr/info/coal_support_info.do","title":"연탄전환 에너지바우처 지원기준","status":"공식 본문 확인","as_of":"2026","checked_at":"2026-09-17","supports":"A02 대상·제외·금액·사용기간"},{"id":"G031-S04","url":"https://www.energyv.or.kr/info/coal_apl_info.do","title":"연탄전환 에너지바우처 신청안내","status":"공식 본문 확인","as_of":"2026","checked_at":"2026-09-17","supports":"A02 신청·재신청·서류·실물카드"}],"conditions":[{"id":"G031-C01","group":"소득·수급 자격","group_logic":"모두 충족","requirement":"생계·의료·주거·교육급여 수급","detail":"신청일 기준 수급 자격 확인","applies_to":"A01 수급자","relation":"세대원 특성 묶음(C02,C05~C11) 중 하나와 모두 충족","source_ids":["G031-S01","G031-S02"],"verification":"공식 본문 확인"},{"id":"G031-C02","group":"세대원 특성","group_logic":"묶음 안 하나 충족","requirement":"노인","detail":"주민등록기준 1961-12-31 이전 출생자","applies_to":"A01 본인 또는 등본상 세대원","relation":"C01과 모두 충족; 세대원 특성 C05~C11과 대체 가능","source_ids":["G031-S01"],"verification":"공식 본문 확인"},{"id":"G031-C03","group":"제외·중복","group_logic":"제외","requirement":"세대원 모두 보장시설에서 급여 수급","detail":"전원 해당 시 제외","applies_to":"A01 세대","relation":"C01 및 세대원 특성을 충족해도 적용","source_ids":["G031-S01"],"verification":"공식 본문 확인"},{"id":"G031-C04","group":"동절기 중복","group_logic":"제외","requirement":"긴급복지 동절기 연료비·2026 연탄쿠폰·2026 연탄전환 바우처 수혜 세대","detail":"일반 A01 동절기 지원과 중복 불가","applies_to":"G031-A01 세대","relation":"C01 및 세대원 특성을 충족해도 적용","source_ids":["G031-S01"],"verification":"공식 본문 확인"},{"id":"G031-C05","group":"세대원 특성","group_logic":"묶음 안 하나 충족","requirement":"영유아","detail":"2019-01-01 이후 출생한 7세 이하 취학 전 아동","applies_to":"A01 본인 또는 등본상 세대원","relation":"C01과 모두 충족","source_ids":["G031-S01"],"verification":"공식 본문 확인"},{"id":"G031-C06","group":"세대원 특성","group_logic":"묶음 안 하나 충족","requirement":"등록 장애인","detail":"장애인복지법에 따라 등록","applies_to":"A01 본인 또는 등본상 세대원","relation":"C01과 모두 충족","source_ids":["G031-S01"],"verification":"공식 본문 확인"},{"id":"G031-C07","group":"세대원 특성","group_logic":"묶음 안 하나 충족","requirement":"임산부","detail":"임신 중 또는 분만 후 6개월 미만","applies_to":"A01 본인 또는 등본상 세대원","relation":"C01과 모두 충족","source_ids":["G031-S01"],"verification":"공식 본문 확인"},{"id":"G031-C08","group":"세대원 특성","group_logic":"묶음 안 하나 충족","requirement":"중증·희귀·중증난치질환자","detail":"본인일부부담금 산정특례 기준의 해당 질환 보유","applies_to":"A01 본인 또는 등본상 세대원","relation":"C01과 모두 충족","source_ids":["G031-S01"],"verification":"공식 본문 확인"},{"id":"G031-C09","group":"세대원 특성","group_logic":"묶음 안 하나 충족","requirement":"한부모가족","detail":"한부모가족지원법 제5조·제5조의2 지원대상","applies_to":"A01 본인 또는 등본상 세대원","relation":"C01과 모두 충족","source_ids":["G031-S01"],"verification":"공식 본문 확인"},{"id":"G031-C10","group":"세대원 특성","group_logic":"묶음 안 하나 충족","requirement":"소년소녀가정","detail":"가정위탁보호 아동 포함","applies_to":"A01 본인 또는 등본상 세대원","relation":"C01과 모두 충족","source_ids":["G031-S01"],"verification":"공식 본문 확인"},{"id":"G031-C11","group":"세대원 특성","group_logic":"묶음 안 하나 충족","requirement":"다자녀세대","detail":"부 또는 모와 그 19세 미만 자녀 2명 이상; 등본상 가정위탁보호아동 포함","applies_to":"A01 세대","relation":"C01과 모두 충족","source_ids":["G031-S01"],"verification":"공식 본문 확인"},{"id":"G031-C12","group":"연탄전환 설비","group_logic":"모두 충족","requirement":"2026년 1월 이후 연탄보일러를 비연탄보일러로 교체","detail":"교체 이력·설치시공 확인 필요","applies_to":"A02 세대","relation":"A02 취약계층 유형 C13~C18 중 하나와 모두 충족","source_ids":["G031-S03","G031-S04"],"verification":"공식 본문 확인"},{"id":"G031-C13","group":"연탄전환 취약계층","group_logic":"묶음 안 하나 충족","requirement":"기초생활수급자","detail":"생계·의료·주거·교육급여 수급 세대","applies_to":"A02 세대","relation":"C12와 모두 충족","source_ids":["G031-S03"],"verification":"공식 본문 확인"},{"id":"G031-C14","group":"연탄전환 취약계층","group_logic":"묶음 안 하나 충족","requirement":"차상위계층","detail":"수급자가 아니면서 소득인정액 기준 중위소득 50% 이하 세대","applies_to":"A02 세대","relation":"C12와 모두 충족","source_ids":["G031-S03"],"verification":"공식 본문 확인"},{"id":"G031-C15","group":"연탄전환 취약계층","group_logic":"묶음 안 하나 충족","requirement":"노인","detail":"1961-12-31 이전 출생자","applies_to":"A02 세대","relation":"C12와 모두 충족","source_ids":["G031-S03"],"verification":"공식 본문 확인"},{"id":"G031-C16","group":"연탄전환 취약계층","group_logic":"묶음 안 하나 충족","requirement":"등록 장애인","detail":"장애인복지법 등록","applies_to":"A02 세대","relation":"C12와 모두 충족","source_ids":["G031-S03"],"verification":"공식 본문 확인"},{"id":"G031-C17","group":"연탄전환 취약계층","group_logic":"묶음 안 하나 충족","requirement":"한부모가족","detail":"한부모가족지원법 지원대상","applies_to":"A02 세대","relation":"C12와 모두 충족","source_ids":["G031-S03"],"verification":"공식 본문 확인"},{"id":"G031-C18","group":"연탄전환 취약계층","group_logic":"묶음 안 하나 충족","requirement":"소년소녀가정","detail":"가정위탁보호 아동 포함","applies_to":"A02 세대","relation":"C12와 모두 충족","source_ids":["G031-S03"],"verification":"공식 본문 확인"},{"id":"G031-C19","group":"연탄전환 제외","group_logic":"제외","requirement":"동절기 연료비·2026 연탄쿠폰·2026 동절기 에너지바우처 수혜, 보장시설 전원수급, 교정·치료감호시설 전원수용","detail":"A02 대상에서 제외","applies_to":"A02 세대","relation":"C12 및 C13~C18 충족해도 적용","source_ids":["G031-S03"],"verification":"공식 본문 확인"},{"id":"G031-C20","group":"연탄전환 경로별 증빙","group_logic":"행동별 분기","requirement":"본인부담 등 기타 전환은 2025년 이후 연탄쿠폰 수급 이력","detail":"2026년 1월 이후 설치·시공 완료 확인서 제출. 재단·지자체 지원 경로는 해당 지원결정 증빙 적용.","applies_to":"G031-A02 중 본인부담 등 기타 전환 세대","relation":"C12 및 취약계층 묶음과 함께, 선택한 전환 경로에 적용","source_ids":["G031-S04"],"verification":"공식 본문 확인"}],"overview_source_ids":["G031-S01","G031-S02","G031-S03","G031-S04"]}'::jsonb);
