INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G034','{"program_id":"G034","title":"농축산물 할인지원 행사","target":"선정 유통업체·점포에서 국산 신선 농축산물을 구매하는 소비자","eligibility_logic":"국산 신선 농축산물 AND 해당 행사 회차의 참여업체·지점 AND 지정 품목 AND 해당 회차 한도·쿠폰 또는 결제 조건. 일반 사업 안내의 할인율·한도와 개별 주간 행사 조건은 구분한다.","benefit":"국산 농축산물 구매 할인 지원. 일반 사업 소개는 20~30%, 1인 주 1만 원(전통시장 2만 원)으로 안내하나 회차별 조건은 별도 확인.","application_period":"공식 사업소개는 2026년 1~12월 추진계획을 안내; 개별 행사 기간은 품목·공지에서 확인","usage_period":"개별 행사 기간·참여업체 조건에 따름","documents":"일반 소비자 구매 할인에 별도 서류 확인 안 됨","application_method":"공식 사이트의 할인품목·참여업체·공지에서 이용 날짜의 회차와 점포 조건을 확인 후 구매한다.","status":"공식 본문 확인","caveat":"확인 가능한 주간 품목 화면은 2026년 1~6월 회차여서 2026-09-17 현재 품목·점포·할인율·한도는 확정하지 않음.","action_ids":["G034-A01"],"sources":[{"id":"G034-S01","url":"https://sale.foodnuri.go.kr/ft/info/list.do","title":"농축산물 할인지원 사업소개","status":"공식 본문 확인","as_of":"2026","checked_at":"2026-09-17","supports":"대상품목, 일반 할인·한도, 선정 유통업체, 연간 추진계획"},{"id":"G034-S02","url":"https://sale.foodnuri.go.kr/ft/ftSale/list.do","title":"농축산물 할인지원 할인품목","status":"공식 본문 확인","as_of":"2026-01~06 확인","checked_at":"2026-09-17","supports":"회차·업체별 품목 및 할인점 차이, 현재 회차 미확정 주의"}],"conditions":[{"id":"G034-C01","group":"대상품목","group_logic":"모두 충족","requirement":"국산 신선 농축산물의 해당 회차 지정 품목 구매","detail":"전체 국산 농축산물이 자동 대상은 아님","applies_to":"구매 건·G034-A01","relation":"참여업체·회차 조건과 AND","source_ids":["G034-S01","G034-S02"],"verification":"공식 본문 확인"},{"id":"G034-C02","group":"참여 경로·한도","group_logic":"모두 충족","requirement":"선정 유통업체·지점의 해당 회차 할인 조건 충족","detail":"일반 안내 한도와 쿠폰·결제·점포별 조건을 같은 값으로 확정하지 않음","applies_to":"구매 건·G034-A01","relation":"대상품목·기간과 AND","source_ids":["G034-S01","G034-S02"],"verification":"공식 본문 확인"}],"overview_source_ids":["G034-S01","G034-S02"]}'::jsonb);
