INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G038','{"program_id":"G038","title":"폐가전 무상방문수거 예약","target":"전국 방문수거 대상 폐가전을 배출하려는 주민","eligibility_logic":"단일수거 대상 대형·중대형 품목은 1개부터, 다량 배출 대상 중소형 품목은 5개 이상부터 가능하다. 추가 초소형 품목은 단일·다량 대상품목과 함께만 가능하다. 품목·수량 분기 AND 수거불가·현장 안전 조건을 충족해야 한다.","benefit":"폐가전 방문수거 서비스.","application_period":"상시 예약 안내","usage_period":"지역별 수거 가능 요일에 따름","documents":"공식 안내에서 일반 예약 서류 확인 안 됨","application_method":"1599-0903 웹 또는 콜센터로 수거 품목과 배출 장소를 예약한다.","status":"공식 본문 확인","caveat":"가구류 등 비대상 품목, 광물·가스·기름 혼용 제품, 원형 훼손 제품은 수거 불가로 안내된다. 지역별 수거일은 확인 필요.","action_ids":["G038-A01"],"sources":[{"id":"G038-S01","url":"https://www.15990903.or.kr/portal/cnts/userGuide.do","title":"폐가전 무상 방문수거 이용안내","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"전국 예약, 단일·다량·추가 품목 수량 분기, 운영일, 배출 유의사항"},{"id":"G038-S02","url":"https://www.15990903.or.kr/portal/cnts/selectContents.do?cntnts_id=A1000005","title":"폐가전 무상 방문수거 수거품목 및 기준","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"단일수거, 다량 5개 이상, 수거 불가 품목 및 철거 조건"}],"conditions":[{"id":"G038-C01","group":"단일 수거","group_logic":"묶음 안 하나 충족","requirement":"단일수거 가능 대형·중대형 품목 1개 이상","detail":"냉장고·세탁기·에어컨·31인치 이상 디스플레이·태양광 패널 및 규격 기준을 충족하는 기타 전기·전자 제품","applies_to":"배출 품목·G038-A01","relation":"다량 수거와 OR; 현장 조건과 AND","source_ids":["G038-S01","G038-S02"],"verification":"공식 본문 확인"},{"id":"G038-C02","group":"다량 수거","group_logic":"묶음 안 하나 충족","requirement":"다량 배출 대상 중소형 품목 5개 이상","detail":"30인치 이하 디스플레이 및 치수합 50~150cm 미만 또는 1~12kg 미만 기타 전기·전자 제품","applies_to":"배출 품목·G038-A01","relation":"단일 수거와 OR; 5개 미만 소형가전 단독 요청은 수거 불가","source_ids":["G038-S01","G038-S02"],"verification":"공식 본문 확인"},{"id":"G038-C03","group":"추가 품목","group_logic":"조건부","requirement":"초소형 제품은 단일 또는 다량 수거 대상품목과 함께 배출","detail":"무선이어폰·전자담배·전동칫솔·전기면도기 등, 치수합 50cm 미만 또는 1kg 미만","applies_to":"추가 배출 품목","relation":"단독 수거 조건이 아님","source_ids":["G038-S01"],"verification":"공식 본문 확인"},{"id":"G038-C04","group":"제외·현장 조건","group_logic":"제외","requirement":"혼용·원형 훼손·비대상 품목에 해당하지 않고 고정 설치 제품은 사전 철거","detail":"인력 수거 불가 제품은 수거 가능한 상태로 조치; 수거 후 반환 불가","applies_to":"배출 장소·품목","relation":"단일 또는 다량 수거 조건과 AND","source_ids":["G038-S01","G038-S02"],"verification":"공식 본문 확인"}],"overview_source_ids":["G038-S01","G038-S02"]}'::jsonb);
