INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G039','{"program_id":"G039","title":"서울새활용플라자 토요일 개인 투어·체험","target":"서울새활용플라자 탐방 또는 체험 프로그램에 참여하려는 개인","eligibility_logic":"프로그램별 접수 상태 AND 해당 회차·인원·연령 또는 프로그램 고지 조건 AND 사전예약이 필요한 경우 예약 완료. 일반 새활용 탐방 안내에서는 개인이 7세 이상부터 참여 가능하고 정기 탐방은 탐방일 3일 전까지 예약 가능하다고 안내한다.","benefit":"새활용 탐방 및 회차별 투어·체험교육 참여.","application_period":"프로그램·회차별 상이; 공식 프로그램 목록에서 접수 상태 확인","usage_period":"예약한 회차에 한함","documents":"일반 개인 탐방은 별도 서류 확인 안 됨; 30명 이상 단체는 신청서·이메일 접수 안내","application_method":"서울새활용플라자 프로그램의 해당 투어·체험교육 또는 새활용 탐방에서 회차·접수 상태를 확인하여 예약한다.","status":"공식 본문 확인","caveat":"토·일 정기 탐방 시간·무료 여부는 일반 탐방 페이지에 있으나 2026-09-17 특정 토요일 체험의 실제 잔여석·연령·비용은 프로그램별로 다시 확인해야 함.","action_ids":["G039-A01"],"sources":[{"id":"G039-S01","url":"https://www.seoulup.or.kr/program.do?type=Learning","title":"서울새활용플라자 새활용 탐방","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"개인 7세 이상, 예약 마감·인원, 요일·회차, 단체 신청"},{"id":"G039-S02","url":"https://www.seoulup.or.kr/program.do?type=Education","title":"서울새활용플라자 투어·체험교육 프로그램","status":"공식 본문 확인","as_of":"2026 프로그램 목록","checked_at":"2026-09-17","supports":"프로그램별 접수 상태·일정·참여비가 다름"}],"conditions":[{"id":"G039-C01","group":"개인 탐방 대상","group_logic":"모두 충족","requirement":"개인 탐방은 7세 이상","detail":"일반 새활용 탐방 안내의 개인 참여 기준","applies_to":"개인·G039-A01","relation":"회차 예약 조건과 AND","source_ids":["G039-S01"],"verification":"공식 본문 확인"},{"id":"G039-C02","group":"회차·예약","group_logic":"모두 충족","requirement":"해당 프로그램의 접수 상태·회차·인원 조건 충족","detail":"정기 탐방은 3일 전까지 예약 안내; 5인 미만 취소 또는 30명 이상 마감 가능","applies_to":"예약 건·G039-A01","relation":"대상 기준과 AND","source_ids":["G039-S01","G039-S02"],"verification":"공식 본문 확인"}],"overview_source_ids":["G039-S01","G039-S02"]}'::jsonb);
