INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G042','{"program_id":"G042","title":"빈병 보증금 반환","target":"보증금이 포함된 재사용 빈용기를 반환하는 소비자","eligibility_logic":"보증금 대상 빈용기 AND 재사용 표시 또는 보증금 포함 여부 확인 AND 반환 가능한 상태. 1일 반환 수량 제한과 용기 상태 거부 사유는 별도 적용한다.","benefit":"반환한 빈용기의 규격별 보증금 환급.","application_period":"상시 반환","usage_period":"영업시간 내 반환 안내","documents":"일반 반환에 서류 없음","application_method":"반환지원서비스에서 반환처를 찾거나 보증금 대상 제품을 취급하는 소매점에 빈용기를 반환한다.","status":"공식 본문 확인","caveat":"일반 유리병의 분리배출 표시와 보증금 대상 빈용기의 재사용 표시를 구분해야 한다. 1회용 컵 보증금은 이 행동과 분리.","action_ids":["G042-A01"],"sources":[{"id":"G042-S01","url":"https://www.cosmo.or.kr/menu.es?mid=a10201000000","title":"자원순환보증금관리센터 빈용기 제도안내","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"대상 용기·규격별 보증금·재사용 표시"},{"id":"G042-S02","url":"https://singo.cosmo.or.kr/menu.es?mid=a30101000000","title":"빈용기 반환 신고센터 안내","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"소매점 반환 의무, 1일 30병 수량 예외, 훼손·오염·표시 확인 불가 예외"}],"conditions":[{"id":"G042-C01","group":"대상 빈용기","group_logic":"모두 충족","requirement":"보증금 부과 대상 제품의 재사용 빈용기","detail":"소주·맥주·청량음료 등 대상이며 규격별 보증금 차등","applies_to":"반환 용기·G042-A01","relation":"수량·용기 상태 조건과 AND","source_ids":["G042-S01"],"verification":"공식 본문 확인"},{"id":"G042-C02","group":"1일 반환 수량","group_logic":"제외","requirement":"동일인이 1일 30병을 초과하여 반환하는 부분은 소매점이 거부 가능","detail":"해당 소매점에서 구입한 것으로 확인되면 30병 초과분도 거부할 수 없음","applies_to":"반환자·반환 건","relation":"대상 용기 및 용기 상태 조건과 함께 적용","source_ids":["G042-S02"],"verification":"공식 본문 확인"},{"id":"G042-C03","group":"용기 상태","group_logic":"제외","requirement":"훼손·파손·오염되어 재사용이 어렵거나 보증금 포함 여부를 확인할 수 없는 용기는 반환 거부 가능","detail":"재사용 표시·보증금 포함 여부 확인이 필요","applies_to":"반환 용기","relation":"수량 제한과 별개의 거부 사유","source_ids":["G042-S01","G042-S02"],"verification":"공식 본문 확인"}],"overview_source_ids":["G042-S01","G042-S02"]}'::jsonb);
