INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G047','{"program_id":"G047","title":"서울 노원구 베란다형 미니태양광 설치비 지원","target":"노원구 베란다형 미니태양광 설치 희망자","eligibility_logic":"노원구 공고의 설치·보급업체·예산 요건을 충족해야 하나, 공고 전문은 확보하지 못했다.","benefit":"공공 에너지정책 포털은 최대 160만원으로 표시하나, 설비·자부담·물량별 금액 원문은 미확인.","application_period":"2026-04-27~11-30으로 공공 포털 표시; 노원구 검색결과에는 4월 6일 예산 소진 마감 공고가 확인됨.","usage_period":"설치 사업; 별도 사용기간 없음.","documents":"공고 전문 미확인.","application_method":"참여 보급업체·노원구 탄소중립도시과에 확인 후 신청.","status":"2026 공식 검색결과·공공 포털 확인, 공고 전문 미확인","caveat":"검색 결과의 예산 소진 마감과 포털의 11월 30일 표기가 충돌하므로, 신규 신청 가능 여부와 금액을 확정하지 않는다.","action_ids":["G047-A01"],"sources":[{"id":"G047-S01","url":"https://www.nowon.kr/health/index.do","title":"노원구청 검색결과","status":"공식 검색결과만 확인","as_of":"2026","checked_at":"2026-09-17","supports":"2026 공고 및 예산 소진 마감 표시"},{"id":"G047-S02","url":"https://www.e-policy.or.kr/web/index.do","title":"에너지정책소통센터","status":"공식 검색결과만 확인","as_of":"2026","checked_at":"2026-09-17","supports":"지원혜택 최대 160만원·신청기간 표시"}],"conditions":[{"id":"G047-C01","group":"지역·설치","group_logic":"모두 충족","requirement":"노원구 베란다형 미니태양광 설치사업 대상","detail":"거주·설치장소·공동주택 동의 등은 공고 전문 재확인 필요","applies_to":"신청자·설치 장소","relation":"예산·업체 조건과 모두 충족","source_ids":["G047-S01"],"verification":"공식 검색결과만 확인"},{"id":"G047-C02","group":"예산 상태","group_logic":"제한","requirement":"예산 범위","detail":"구청 검색 결과가 예산 소진 마감을 표시","applies_to":"G047-A01","relation":"자격과 별도로 신규 접수 제한 가능","source_ids":["G047-S01"],"verification":"공식 검색결과만 확인"}],"overview_source_ids":["G047-S01","G047-S02"]}'::jsonb);
