INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G080','{"program_id":"G080","title":"서울 종로구 저소득 어르신 냉난방물품 지원","target":"기존 자료상 종로구 만 65세 이상 법정·사각지대 저소득 어르신","eligibility_logic":"기존 자료는 연령 AND 저소득, 타 부서 지원 중복 제외, 동주민센터 선정이라고 하나 2026 원문 미확인.","benefit":"기존 자료상 폭염·한파 대응 냉난방물품; 물품·시기 미확인.","application_period":"비정기 선정으로 기존 자료에만 있음.","usage_period":"해당 없음.","documents":"미확인.","application_method":"관할 동주민센터에 선정시기·대상·중복 여부 문의.","status":"현재 공식 원문 접근 실패","caveat":"정부24 원문을 열지 못해 2026 운영 여부, 선정기준, 지원물품을 확정하지 않는다.","action_ids":["G080-A01"],"sources":[{"id":"G080-S01","url":"https://www.gov.kr/portal/rcvfvrSvc/dtlEx/300000000174","title":"종로구 저소득 어르신 냉난방물품 지원","status":"접근 실패","as_of":"미표시","checked_at":"2026-09-17","supports":"현재 원문 확인 시도"}],"conditions":[{"id":"G080-C02","group":"연령","group_logic":"모두 충족(기존 자료)","requirement":"만 65세 이상","detail":"기존 자료","applies_to":"대상자 또는 세대","relation":"저소득 조건과 모두 충족","source_ids":["G080-S01"],"verification":"접근 실패; 기존 자료만"},{"id":"G080-C03","group":"저소득","group_logic":"모두 충족(기존 자료)","requirement":"법정 저소득 또는 사각지대 저소득","detail":"기존 자료","applies_to":"대상자 또는 세대","relation":"동주민센터 선정 대상","source_ids":["G080-S01"],"verification":"접근 실패; 기존 자료만"},{"id":"G080-C04","group":"선정","group_logic":"모두 충족(기존 자료)","requirement":"동주민센터가 대상자 선정","detail":"일반 공모 신청 여부 미확인","applies_to":"대상자 또는 세대","relation":"연령·저소득 조건 후 적용","source_ids":["G080-S01"],"verification":"접근 실패; 기존 자료만"},{"id":"G080-C05","group":"중복","group_logic":"제외(기존 자료)","requirement":"타 부서 소관 지원사업 중복 제외","detail":"기존 자료","applies_to":"대상자 또는 세대","relation":"앞 조건을 충족해도 제외","source_ids":["G080-S01"],"verification":"접근 실패; 기존 자료만"}],"overview_source_ids":["G080-S01"]}'::jsonb);
