INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G101','{"program_id":"G101","title":"신재생에너지 설비 고장접수·A/S 연결","target":"고장 또는 불편이 있는 신재생에너지 설비의 A/S를 요청하려는 신청자·설비 소유자","eligibility_logic":"신재생에너지 설비 A/S 또는 불만 신고를 위한 접수 서비스다. 필수 개인정보 수집 동의 AND 신청자 연락처가 필요하며, 접수 양식은 설비소유자·설치장소·설비정보·고장 상태를 받는다. 접수 뒤 상담원 확인전화가 안내된다.","benefit":"신재생에너지 설비 A/S 및 불만 신고 접수·상담 연결.","application_period":"상시 접수 화면 확인","usage_period":"접수 후 상담·A/S 처리 절차에 따름","documents":"접수 양식에 설비 정보·설치업체 정보 등을 입력; 별도 첨부 서류 요건은 확인하지 못함","application_method":"고장접수 지원센터의 개인정보 동의 후 고장신고서를 작성·등록하거나, 설치 참여기업 또는 통합 콜센터에 A/S를 요청한다.","status":"공식 본문 확인","caveat":"신규 설치 보조사업의 소유·설치 기준, 참여기업 선정 조건은 고장접수 이용 자격으로 혼합하지 않음.","action_ids":["G101-A01"],"sources":[{"id":"G101-S01","url":"https://nr.energy.or.kr/frsc/BR/FR/AcceptTerms.do","title":"신재생에너지 설비 고장접수 지원센터 개인정보 동의","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"필수 동의와 A/S 접수 서비스 이용 제한 안내"},{"id":"G101-S02","url":"https://nr.energy.or.kr/frsc/BR/FR/BRFRList.do","title":"신재생 에너지 설비 A/S 및 불만 신고서","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"접수 양식 항목과 접수 후 확인전화"},{"id":"G101-S03","url":"https://nr.energy.or.kr/A0/GN_03/GN_03_00_020.do","title":"한국에너지공단 그린홈 A/S 안내","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"설치 참여기업 또는 고장접수지원센터 요청 안내"}],"conditions":[{"id":"G101-C01","group":"접수 동의·연락","group_logic":"모두 충족","requirement":"필수 개인정보 수집·이용 동의와 신청자 연락처","detail":"필수 동의 거부 시 고장접수 지원 서비스 이용 제한 안내","applies_to":"신청자·G101-A01","relation":"설비·고장 정보와 AND","source_ids":["G101-S01","G101-S02"],"verification":"공식 본문 확인"},{"id":"G101-C02","group":"설비·고장 정보","group_logic":"모두 충족","requirement":"설비소유자·설치장소·설비구분 및 고장 상태 입력","detail":"설비관리번호·설치년도·설치업체 정보는 양식에 제시되며 일부는 보조 입력으로 보임","applies_to":"설비·접수 건","relation":"접수 동의·연락 조건과 AND","source_ids":["G101-S02"],"verification":"공식 본문 확인"}],"overview_source_ids":["G101-S01","G101-S02","G101-S03"]}'::jsonb);
