INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:G117','{"program_id":"G117","title":"UN CC:Learn 온라인 기후교육","target":"Net Zero 101 온라인 강좌를 수강하려는 사람","eligibility_logic":"현재 강좌 카탈로그는 자가학습·영어·무료 인증서·약 1.5시간을 안내한다. 2024 syllabus는 선수요건 없음, 3개 모듈 및 모듈별 퀴즈 성공 완료 후 디지털 인증서를 안내한다. 기존 자료의 ‘각 퀴즈 75%’ 수치는 현재 공식 강좌 화면에서 재확인하지 못했으므로 현재 조건으로 확정하지 않는다.","benefit":"Net Zero 101 자가학습과 무료 디지털 인증서 안내.","application_period":"자가학습 과정; 별도 마감일 확인 안 됨","usage_period":"자가학습 진행","documents":"공식 카탈로그·syllabus에서 서류 요건 확인 안 됨","application_method":"UN CC:Learn에서 계정 등록 또는 로그인 후 해당 강좌에 등록해 수강한다.","status":"공식 본문 확인 및 구연도 자료 병기","caveat":"무료 인증서는 Net Zero 101에 한정하며, 다른 강좌의 비용·언어·인증 조건으로 일반화하지 않는다. 75% 점수 기준은 2024 이전 자료로 현재 유효성 미확인.","action_ids":["G117-A01"],"sources":[{"id":"G117-S01","url":"https://unccelearn.org/course/view.php?id=185&page=overview","title":"Net Zero 101: What, Why and How","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"강좌 존재 및 과정 페이지"},{"id":"G117-S02","url":"https://unccelearn.org/courses/?lang=en&language=en","title":"UN CC:Learn Courses Catalog","status":"공식 본문 확인","as_of":"2026-09-17 화면","checked_at":"2026-09-17","supports":"자가학습·영어·무료 인증서·약 1.5시간"},{"id":"G117-S03","url":"https://unccelearn.org/pluginfile.php/929251/format_unccelearn/syllabus/0/Net%20Zero%20101%20Syllabus.pdf","title":"Net Zero 101 syllabus","status":"기존 자료만","as_of":"2024-04-19","checked_at":"2026-09-17","supports":"선수요건 없음, 3개 모듈, 퀴즈 완료와 인증서 안내"}],"conditions":[{"id":"G117-C01","group":"수강","group_logic":"안내","requirement":"선수요건 없음; 영어 자가학습 강좌","detail":"2024 syllabus의 선수요건 없음은 현재 세부 화면에서 재확인하지 못함","applies_to":"수강 행동·G117-A01","relation":"수료증 조건과 분리","source_ids":["G117-S02","G117-S03"],"verification":"공식 본문 확인 및 기존 자료만"},{"id":"G117-C02","group":"수료증","group_logic":"모두 충족","requirement":"3개 모듈 및 각 모듈 퀴즈의 성공 완료 후 디지털 인증서","detail":"75% 수치 기준은 기존 입력 자료와 달리 현재 공식 본문에서 확인하지 못해 미확정","applies_to":"수료증·G117-A01","relation":"수강 시작 자격이 아니라 수료 결과 조건","source_ids":["G117-S03"],"verification":"기존 자료만"}],"overview_source_ids":["G117-S01","G117-S02","G117-S03"]}'::jsonb);
