INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:KR-CNP-GREEN-2026','{"program_id":"KR-CNP-GREEN-2026","title":"탄소중립포인트 녹색생활실천","target":"일상생활 속 친환경 활동을 실천하는 국민","eligibility_logic":"회원가입 AND 선택한 실천항목의 참여채널·참여기업 조건 충족 AND 참여실적 연계가 필요하다. 17개 입력 행동은 항목별로 독립되어 참여기업·지역·설정이 다를 수 있다.","benefit":"현금·민간기업 포인트·기부 중 선택 가능, 1인당 연 최대 70,000원. 항목별 단가·예산은 변동 가능하고 실천 후 익월 말일부터 지급 안내.","application_period":"상시 회원가입 안내","usage_period":"항목·참여기업별 운영 및 예산 상황에 따름","documents":"회원가입 시 신원·연락·지급수단 등 정보 처리 안내; 개별 실천은 별도 증빙 제출이 원칙적으로 불필요하나 참여기업 연계 필요","application_method":"누리집 회원가입 → 항목별 참여방법/참여기업 설정 → 실천 → 포인트 적립 → 지급수단 수령","status":"공식 17개 항목·참여방법·2026 FAQ 확인","caveat":"입력의 17개 행동은 공식 17개 항목과 ID·제목을 대조했다. 참여기업 수·단가·예산 및 개별 지역 이용 가능성은 수시 변동한다.","action_ids":["KR-CNP-GREEN-2026-A01","KR-CNP-GREEN-2026-A02","KR-CNP-GREEN-2026-A03","KR-CNP-GREEN-2026-A04","KR-CNP-GREEN-2026-A05","KR-CNP-GREEN-2026-A06","KR-CNP-GREEN-2026-A07","KR-CNP-GREEN-2026-A08","KR-CNP-GREEN-2026-A09","KR-CNP-GREEN-2026-A10","KR-CNP-GREEN-2026-A11","KR-CNP-GREEN-2026-A12","KR-CNP-GREEN-2026-A13","KR-CNP-GREEN-2026-A14","KR-CNP-GREEN-2026-A15","KR-CNP-GREEN-2026-A16","KR-CNP-GREEN-2026-A17"],"sources":[{"id":"KR-CNP-GREEN-2026-S01","url":"https://www.cpoint.or.kr/netzero/site/cntnts/CNTNTS_001.do","title":"제도소개","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"대상·회원가입·17항목·혜택과 연 최대 한도"},{"id":"KR-CNP-GREEN-2026-S02","url":"https://www.cpoint.or.kr/netzero/site/cntnts/CNTNTS_002.do","title":"인센티브 안내","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"항목별 단가·참여채널·예산 변동"},{"id":"KR-CNP-GREEN-2026-S03","url":"https://www.cpoint.or.kr/netzero/site/cntnts/CNTNTS_003.do","title":"참여방법","status":"공식 본문 확인","as_of":"미표시","checked_at":"2026-09-17","supports":"회원가입부터 수령까지의 절차 및 행동별 방식"},{"id":"KR-CNP-GREEN-2026-S04","url":"https://www.cpoint.or.kr/netzero/faq/nv_faqList.do","title":"FAQ","status":"공식 본문 확인","as_of":"2026","checked_at":"2026-09-17","supports":"자동 실적연계·지급수단·2