INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:SDG-FOOD-REDUCER-H2-2026','{"program_id":"SDG-FOOD-REDUCER-H2-2026","title":"성동구 하반기 가정용 음식물류폐기물 소형감량기 구매 지원","target":"2026-08-20 현재 성동구 거주 주민으로 가정용 소형감량기를 구매·설치한 세대","eligibility_logic":"기준일 성동구 거주 AND 같은 주소지 1대 AND 공고의 인증·제품·구매·증빙 조건 충족 AND 예산 범위 선정이 필요하다. 렌탈·주방용 오물분쇄기·타 사업 중복 및 자체감량기 설치시설은 제외된다.","benefit":"구매비의 30%, 최대 210,000원; 약 100대, 예산 범위 내 선착순","application_period":"당초 공고 2026-09-01~09-11; 공식 신속예약 목록은 지원신청을 2026-08-24~09-30 운영으로 표시","usage_period":"증빙 제출 2026-09-01~11-30, 실적 제출 2026-08-24~12-31로 공식 예약 목록 표시","documents":"주민등록등본 1부 및 공고 첨부 신청서·구매증빙·사용전후 실적 서식","application_method":"동주민센터 방문 또는 성동구 신속예약 신청 후 공고의 증빙·실적 제출","status":"공식 공고 및 신속예약 목록 확인","caveat":"당초 공고 기간과 현재 신속예약 목록의 신청 종료일이 다르다. 2026-09-17 현재 접수 가능 여부·정원은 예약 상세에서 재확인해야 한다.","action_ids":["SDG-FOOD-REDUCER-H2-2026-A01"],"sources":[{"id":"SDG-FOOD-REDUCER-H2-2026-S01","url":"https://bogunso.sd.go.kr/main/selectBbsNttView.do?bbsNo=184&key=3781&nttNo=360685&nttShowPd=60&pageIndex=2&pageUnit=10","title":"성동구 2026년 하반기 소형감량기 구매 지원 공고","status":"공식 본문 확인","as_of":"2026-08-20 공고","checked_at":"2026-09-17","supports":"대상·금액·선착순·당초 신청기간·서류"},{"id":"SDG-FOOD-REDUCER-H2-2026-S02","url":"https://www.sd.go.kr/booking/webPubRveManagerList.do?key=5154","title":"성동구 신속예약 생활서비스 목록","status":"공식 본문 확인","as_of":"2026-09-17 화면","checked_at":"2026-09-17","supports":"현재 표시된 신청·증빙·실적 제출 기간"}],"conditions":[{"id":"SDG-FOOD-REDUCER-H2-2026-C01","group":"거주·세대","group_logic":"모두 충족","requirement":"2026-08-20 현재 성동구 거주, 같은 주소지 1대","detail":"보조금 지급 시까지 주소 유지 조건은 입력의 기존 자료이며 이번 공고 검색결과 본문에서 재확인하지 못함","applies_to":"A01 신청 세대","relation":"제품 조건과 AND","source_ids":["SDG-FOOD-REDUCER-H2-2026-S01"],"verification":"공식 본문 확인; 주소유지 세부는 미확인"},{"id":"SDG-FOOD-REDUCER-H2-2026-C02","group":"제품·제외","group_logic":"모두 충족 및 제외","requirement":"가정용 소형감량기 구매·설치 및 공고 첨부 인증제품 기준 충족","detail":"렌탈·주방용 오물분쇄기·타 사업 중복지원·자체감량기 설치시설 제외는 기존 공식 공고 자료로 제시되나 검색 노출 본문에서 전문 미확인","applies_t