INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:SDG-ZEV-2026','{"program_id":"SDG-ZEV-2026","title":"성동구 친환경자동차 구매보조금","target":"2026-01-01 이후 지원대상 친환경차를 구매한 성동구민","eligibility_logic":"지원대상 차량 구매 AND 서울시 보조금 지급대상 모델 AND 성동구 신청·서류 제출 AND 예산 잔액이 필요하다. 전기차·수소차·전기이륜차는 차종·모델·금액이 각각 분기한다.","benefit":"전기차 최대 500,000원 차등, 수소차 1,000,000원 일괄, 전기이륜차 최대 400,000원 차등; 차종별 대수는 전기차 60·수소차 2·이륜차 50이며 조정 가능","application_period":"2026-02-23부터 예산 소진 시 마감; 공고 종료일 2026-12-31","usage_period":"공고 사업기간 내","documents":"공고 첨부 지원신청서·개인정보 수집이용 동의서 및 차량별 제출서류","application_method":"차량 구매 후 성동구청 기후에너지과에 방문·우편 또는 신속예약으로 접수","status":"공식 공고·신속예약 확인","caveat":"공고는 예산 소진 시 마감이고 차종별 물량 조정 가능이다. 2026-09-17의 잔여 예산·개별 모델 적격은 확인하지 못했다.","action_ids":["SDG-ZEV-2026-A01","SDG-ZEV-2026-A02","SDG-ZEV-2026-A03"],"sources":[{"id":"SDG-ZEV-2026-S01","url":"https://www.sd.go.kr/main/selectBbsNttView.do?bbsNo=184&key=3659&nttNo=356464&nttShowPd=60&pageIndex=16&pageUnit=10","title":"성동구 2026년 친환경자동차 구매보조금 공고","status":"공식 본문 확인","as_of":"2026","checked_at":"2026-09-17","supports":"사업기간·예산·차종별 대수/금액·신청방법"},{"id":"SDG-ZEV-2026-S02","url":"https://bogunso.sd.go.kr/booking/viewTnOnlineRceptU1.do?key=4871&progrmNo=681&sc3=202603","title":"성동구 전기차 구매 보조금 신속예약","status":"공식 본문 확인","as_of":"2026","checked_at":"2026-09-17","supports":"2026-01-01 이후 구매·서울시 지급대상 모델·신청 안내"}],"conditions":[{"id":"SDG-ZEV-2026-C01","group":"거주·구매","group_logic":"모두 충족","requirement":"2026-01-01 이후 친환경차 구매한 성동구민","detail":"차량별 구매·등록 추가 요건은 공고 첨부 전문 확인 필요","applies_to":"A01 전기차, A02 수소차, A03 전기이륜차","relation":"모델·예산 조건과 AND","source_ids":["SDG-ZEV-2026-S02"],"verification":"공식 본문 확인"},{"id":"SDG-ZEV-2026-C02","group":"차종·모델","group_logic":"행동별 분기","requirement":"서울시 보조금 지급대상 모델","detail":"전기차(승용·승합·화물), 수소차(승용), 전기이륜차(경형~대형)로 분기","applies_to":"A01/A02/A03","relation":"C01과 AND","source_ids":["SDG-ZEV-2026-S01","SDG-ZEV-2026-S02"],"verification":"공식 본문 확인"},{"id":"SDG-ZEV-2026-C03","group":"예산·물량","group_logic":"제한","requirement"