INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:SEOUL-EM-BLDG-2026','{"program_id":"SEOUL-EM-BLDG-2026","title":"서울시 에코마일리지 - 건물","target":"서울시 에코마일리지 개인·단체회원; 개인은 가구 대표 1인 기준","eligibility_logic":"회원가입 AND 에너지 고객번호 등록 AND 평가기간 참여 신청 AND 기준 대비 에너지 절감이 필요하다. 개인회원과 단체회원은 대상·보상·평가 분기이며, 기존 입력의 고객번호 2개 이상 세부는 이번 공식 본문에서 재확인하지 못했다.","benefit":"개인회원은 6개월 절감률·연속 절감 조건에 따라 10,000~50,000마일리지; 서울시 2026 안내는 건물 에너지 절약 연 최대 100,000마일리지라고 소개한다.","application_period":"2026-01-05부터 참여신청제 시행; 반기별 평가·모집 일정은 누리집 확인 필요","usage_period":"가입 다음 달부터 6개월 단위 평가라는 기존 2026 서울시 안내","documents":"온라인 고객번호 등록 또는 동주민센터 가입; 별도 서류는 공식 안내에서 미확인","application_method":"에코마일리지 누리집 가입·에너지 고객번호 등록 후 평가기간 참여 신청","status":"2026 서울시 공식 안내 확인","caveat":"50,000과 100,000은 개인 6개월 구간 보상과 건물 연 최대 소개의 서로 다른 범위일 수 있어 합산하지 않았다.","action_ids":["SEOUL-EM-BLDG-2026-A01","SEOUL-EM-BLDG-2026-A02","SEOUL-EM-BLDG-2026-A03","SEOUL-EM-BLDG-2026-A04","SEOUL-EM-BLDG-2026-A05"],"sources":[{"id":"SEOUL-EM-BLDG-2026-S01","url":"https://news.seoul.go.kr/env/archives/566790","title":"에코마일리지제 개편·참여신청제 도입","status":"공식 본문 확인","as_of":"2026-01-06","checked_at":"2026-09-17","supports":"2026-01-05부터 건물 참여신청제"},{"id":"SEOUL-EM-BLDG-2026-S02","url":"https://news.seoul.go.kr/env/archives/568914","title":"에코마일리지 건물편","status":"공식 본문 확인","as_of":"2026-04-27","checked_at":"2026-09-17","supports":"에너지 절감·구간별 개인 보상 안내"},{"id":"SEOUL-EM-BLDG-2026-S03","url":"https://news.seoul.go.kr/env/archives/570488","title":"서울시민 환경 혜택 안내","status":"공식 본문 확인","as_of":"2026-08-26","checked_at":"2026-09-17","supports":"건물 부문 5% 이상 절감·연 최대 10만 마일리지 소개"}],"conditions":[{"id":"SEOUL-EM-BLDG-2026-C01","group":"회원·지역","group_logic":"모두 충족","requirement":"서울 에코마일리지 가입; 개인·단체 유형 분리","detail":"개인 가구 대표와 단체 회원의 지급기준은 별도","applies_to":"A01~A05","relation":"C02·C03과 AND","source_ids":["SEOUL-EM-BLDG-2026-S01","SEOUL-EM-BLDG-2026-S02"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-BLDG-2026-C02","group":"에너지 정보·신청","group_logic":"모두 충족","requirement":"에너지 고객번호 등록 및 평가기간 참여 신청","detail":"기존 자료상 전기 필수·총2개 이상. 이번 본문에서 수량 기준 미확인; 개인/단체별 적용범위 재확인 필요.","applies_to":"A01~A05","relation":"C01·C03과 AND","source_ids":["SEOUL-EM-BLDG-2026-S01"],"verification":"공식 본문 확인; 세부 고객번호 수 미확인"},{"id":"SEOUL-EM-BLDG-2026-C03","group":"절감 평가","group_logic":"모두 충족","requirement":"전기·수도·도시가스 등 에너지 사용량 절감","detail":"6개월 절감률·연속 절감에 따른 구간 보상; 5% 이상 절감은 서울시 종합안내에 기재","applies_to":"A01~A05","relation":"참여 신청 후 평가","source_ids":["SEOUL-EM-BLDG-2026-S02","SEOUL-EM-BLDG-2026-S03"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-BLDG-2026-C04","group":"개인회원 절감 구간","group_logic":"행동별 분기","requirement":"과거 평균 대비 5% 이상~10% 미만 절감","detail":"10,000마일리지/6개월 평가","applies_to":"SEOUL-EM-BLDG-2026-A01","relation":"C01~C03과 AND","source_ids":["SEOUL-EM-BLDG-2026-S02"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-BLDG-2026-C05","group":"개인회원 절감 구간","group_logic":"행동별 분기","requirement":"과거 평균 대비 10% 이상~15% 미만 절감","detail":"30,000마일리지/6개월 평가","applies_to":"SEOUL-EM-BLDG-2026-A02","relation":"C01~C03과 AND","source_ids":["SEOUL-EM-BLDG-2026-S02"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-BLDG-2026-C06","group":"개인회원 절감 구간","group_logic":"행동별 분기","requirement":"과거 평균 대비 15% 이상 절감","detail":"50,000마일리지/6개월 평가","applies_to":"SEOUL-EM-BLDG-2026-A03","relation":"C01~C03과 AND","source_ids":["SEOUL-EM-BLDG-2026-S02"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-BLDG-2026-C07","group":"개인회원 지속 절감","group_logic":"행동별 분기","requirement":"직전 2회 연속 절감 후 0% 초과~5% 미만 절감 유지","detail":"10,000마일리지","applies_to":"SEOUL-EM-BLDG-2026-A04","relation":"C01~C03과 AND","source_ids":["SEOUL-EM-BLDG-2026-S02"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-BLDG-2026-C08","group":"단체회원 절감","group_logic":"행동별 분기","requirement":"서울 소재 개인사업자 등 소상공인 단체회원, 10% 이상 절감","detail":"50,000마일리지/평가","applies_to":"SEOUL-EM-BLDG-2026-A05","relation":"C01~C03과 AND","source_ids":["SEOUL-EM-BLDG-2026-S02"],"verification":"공식 본문 확인"}],"overview_source_ids":["SEOUL-EM-BLDG-2026-S01","SEOUL-EM-BLDG-2026-S02","SEOUL-EM-BLDG-2026-