INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:SEOUL-EM-CAR-2026','{"program_id":"SEOUL-EM-CAR-2026","title":"서울시 에코마일리지 - 승용차","target":"서울시 등록 12인승 이하 비사업용 승용·승합차 소유자","eligibility_logic":"서울시 등록 AND 12인승 이하 비사업용 AND 내연기관 차량 AND 1인 1대(공동소유는 대표) AND 해당 평가기간 시작·종료 주행거리와 사진 등록이 필요하다. 전기·수소·하이브리드는 제외된다.","benefit":"기준 주행거리 대비 감축률 또는 감축량에 따라 최대 50,000마일리지","application_period":"2026 신규 모집은 2월 2~27일(공식 3월 안내 기준)으로 종료; 기존 참여자는 10월 최종 주행거리 등록 안내","usage_period":"2026년 참여 평가기간·10월 최종 등록","documents":"차량번호판과 계기판 사진, 시작·종료 주행거리","application_method":"에코마일리지 누리집 가입 → 참여 신청·시작 주행거리 등록 → 감축 운행 → 종료 주행거리 등록","status":"2026 모집은 마감된 과거 공고로 확인","caveat":"공식 2026-04-06~06-03 특별 이벤트는 별도 30일 이벤트이며 정규 2026 참여 조건·혜택으로 합치지 않았다.","action_ids":["SEOUL-EM-CAR-2026-A01","SEOUL-EM-CAR-2026-A02","SEOUL-EM-CAR-2026-A03","SEOUL-EM-CAR-2026-A04","SEOUL-EM-CAR-2026-A05"],"sources":[{"id":"SEOUL-EM-CAR-2026-S01","url":"https://news.seoul.go.kr/env/archives/567468?listPage=1","title":"2026 승용차 마일리지 2월 신청","status":"공식 본문 확인","as_of":"2026-03-26","checked_at":"2026-09-17","supports":"대상·내연기관 제외·모집·최대 5만 마일리지"},{"id":"SEOUL-EM-CAR-2026-S02","url":"https://news.seoul.go.kr/env/archives/568558","title":"승용차 에코마일리지 특별 이벤트","status":"공식 본문 확인","as_of":"2026-04-10","checked_at":"2026-09-17","supports":"특별 이벤트의 사진 등록·기간·별도 기준"}],"conditions":[{"id":"SEOUL-EM-CAR-2026-C01","group":"차량·소유","group_logic":"모두 충족 및 제외","requirement":"서울시 등록 12인승 이하 비사업용 승용·승합차, 내연기관, 1인 1대","detail":"전기·수소·하이브리드 제외; 공동소유 대표 소유자 등 세부는 기존 자료이며 이번 본문에서 전부 재확인하지 못함","applies_to":"승용차 참여","relation":"C02와 AND","source_ids":["SEOUL-EM-CAR-2026-S01"],"verification":"공식 본문 확인; 일부 세부 미확인"},{"id":"SEOUL-EM-CAR-2026-C02","group":"참여·평가","group_logic":"모두 충족","requirement":"참여 신청 및 시작·종료 주행거리 등록","detail":"특별 이벤트는 차량번호판·계기판 사진을 요구하며 정규 과정의 현재 화면은 미확인","applies_to":"승용차 참여","relation":"C01과 AND","source_ids":["SEOUL-EM-CAR-2026-S01","SEOUL-EM-CAR-2026-S02"],"verification":"공식 본문 확인; 정규 사진요건 미확인"},{"id":"SEOUL-EM-CAR-2026-C03","group":"주행거리 감축 구간","group_logic":"모두 충족","requirement":"주행거리 감축 10% 미만 또는 1,000km 미만","detail":"기존 카탈로그의 구간별 안내: 10,000마일리지 현재 공고의 구간별 전체표는 이번 조사 미확인.","applies_to":"SEOUL-EM-CAR-2026-A01","relation":"차량·참여 조건과 모두 충족; 구간 간 적용은 원래 비율 또는 감축량 기준 확인","source_ids":["SEOUL-EM-CAR-2026-S01","SEOUL-EM-CAR-2026-S02"],"verification":"기존 자료 기준; 구간별 최신 원문 미확인"},{"id":"SEOUL-EM-CAR-2026-C04","group":"주행거리 감축 구간","group_logic":"모두 충족","requirement":"주행거리 감축 10% 이상~20% 미만 또는 1,000~2,000km 미만","detail":"기존 카탈로그의 구간별 안내: 20,000마일리지 현재 공고의 구간별 전체표는 이번 조사 미확인.","applies_to":"SEOUL-EM-CAR-2026-A02","relation":"차량·참여 조건과 모두 충족; 구간 간 적용은 원래 비율 또는 감축량 기준 확인","source_ids":["SEOUL-EM-CAR-2026-S01","SEOUL-EM-CAR-2026-S02"],"verification":"기존 자료 기준; 구간별 최신 원문 미확인"},{"id":"SEOUL-EM-CAR-2026-C05","group":"주행거리 감축 구간","group_logic":"모두 충족","requirement":"주행거리 감축 20% 이상~30% 미만 또는 2,000~3,000km 미만","detail":"기존 카탈로그의 구간별 안내: 30,000마일리지 현재 공고의 구간별 전체표는 이번 조사 미확인.","applies_to":"SEOUL-EM-CAR-2026-A03","relation":"차량·참여 조건과 모두 충족; 구간 간 적용은 원래 비율 또는 감축량 기준 확인","source_ids":["SEOUL-EM-CAR-2026-S01","SEOUL-EM-CAR-2026-S02"],"verification":"기존 자료 기준; 구간별 최신 원문 미확인"},{"id":"SEOUL-EM-CAR-2026-C06","group":"주행거리 감축 구간","group_logic":"모두 충족","requirement":"주행거리 감축 30% 이상~40% 미만 또는 3,000~4,000km 미만","detail":"기존 카탈로그의 구간별 안내: 40,000마일리지 현재 공고의 구간별 전체표는 이번 조사 미확인.","applies_to":"SEOUL-EM-CAR-2026-A04","relation":"차량·참여 조건과 모두 충족; 구간 간 적용은 원래 비율 또는 감축량 기준 확인","source_ids":["SEOUL-EM-CAR-2026-S01","SEOUL-EM-CAR-2026-S02"],"verification":"기존 자료 기준; 구간별 최신 원문 미확인"},{"id":"SEOUL-EM-CAR-2026-C07","group":"주행거리 감축 구간","group_logic":"모두 충족","requirement":"주행거리 감축 40% 이상 또는 4,000km 이상","detail":"기존 카탈로그의 구간별 안내: 50,000마일리지 현재 공고의 구간별 전체표는 이번 조사 미확인.","applies_to":"SEOUL-EM-CAR-2026-A05","relation":"차량·참여 조건과 모두 충족; 구간 간 적용은 원래 비율 또는 감축량 기준 확인","source_ids":["SEOUL-EM-CAR-2026-S01","SEOUL-EM-CAR-2026-S02"],"verification":"기존 자료 기준; 구간별 최신 원문 미확인"}],"overview_source_ids":["SEOUL-EM-CAR-2026-S01","SEOUL-EM-CAR-2026-