INSERT INTO catalog_program (program_key,payload) VALUES ('scheme:SEOUL-EM-GREEN-2026','{"program_id":"SEOUL-EM-GREEN-2026","title":"서울시 에코마일리지 - 녹색실천","target":"에코마일리지 회원; 모집형 세부 항목은 별도 대상·지역·정원 적용","eligibility_logic":"에코마일리지 회원가입 AND 선택한 항목의 신청·인증·기간을 충족한다. 음식물 감량은 RFID 종량기 사용 세대 AND 주택·RFID 정보 등록 AND 회차 모집·관리자 확인이 추가된다. 환경교육은 만14세 이상 서울시민이며 기관별 지역 기준과 연간 한도가 추가된다. 퀴즈·이벤트·행사·운전은 회차별 공고 기준으로 분기한다.","benefit":"온라인 퀴즈·이벤트 100~1,000, 현장 행사·교육 1,000, 운전·음식물 감량 2,000~5,000마일리지. 녹색실천 전체 최대 수급 한도 50,000P 안내가 확인됨.","application_period":"2026-01-05 신설; 음식물 감량·교육·행사는 회차별 모집 및 예산/정원 조건","usage_period":"항목별; 환경교육은 2026년 7~12월 공고","documents":"음식물 감량은 주소·RFID 종량기 정보, 교육은 QR 인증 등 항목별","application_method":"회원 로그인 → 녹색실천 항목 선택 → 항목별 정보 등록·신청·인증","status":"2026 서울시 공식 제도·음식물·교육 공고 확인","caveat":"입력의 A01~A10 제목·ID·금액을 대조했다. 모집형 항목의 현재 정원·기간·예산은 각 회차 공고에서 재확인한다.","action_ids":["SEOUL-EM-GREEN-2026-A01","SEOUL-EM-GREEN-2026-A02","SEOUL-EM-GREEN-2026-A03","SEOUL-EM-GREEN-2026-A04","SEOUL-EM-GREEN-2026-A05","SEOUL-EM-GREEN-2026-A06","SEOUL-EM-GREEN-2026-A07","SEOUL-EM-GREEN-2026-A08","SEOUL-EM-GREEN-2026-A09","SEOUL-EM-GREEN-2026-A10"],"sources":[{"id":"SEOUL-EM-GREEN-2026-S01","url":"https://news.seoul.go.kr/env/archives/566790","title":"에코마일리지제 개편·녹색실천 신설","status":"공식 본문 확인","as_of":"2026-01-06","checked_at":"2026-09-17","supports":"녹색실천 항목군·기본 단가 범위·참여신청제"},{"id":"SEOUL-EM-GREEN-2026-S02","url":"https://news.seoul.go.kr/env/archives/566705","title":"음식물쓰레기 감량 포인트제","status":"공식 본문 확인","as_of":"2025-12-18 공지, 2026 운영","checked_at":"2026-09-17","supports":"RFID 세대·주소/RFID 등록·관리자 확인·감량 기준"},{"id":"SEOUL-EM-GREEN-2026-S03","url":"https://news.seoul.go.kr/env/archives/569743","title":"2026 환경교육포인트제","status":"공식 본문 확인","as_of":"2026-08-04","checked_at":"2026-09-17","supports":"만14세·서울시민·에코마일리지 회원·지역기준·연간 한도"}],"conditions":[{"id":"SEOUL-EM-GREEN-2026-C01","group":"공통 회원·항목 신청","group_logic":"모두 충족","requirement":"에코마일리지 회원으로서 녹색실천 항목별 신청·인증","detail":"퀴즈·온라인/현장 이벤트는 해당 회차 공고와 예산·정원 적용","applies_to":"A01~A10","relation":"항목별 C02~C04와 AND","source_ids":["SEOUL-EM-GREEN-2026-S01"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-GREEN-2026-C02","group":"음식물 감량","group_logic":"모두 충족","requirement":"RFID 종량기 사용 세대, 회원가입, 주소·RFID 정보 등록, 회차 모집·확인","detail":"전년 동기간 대비 감량 성과 기준; 회차별 선착순·기간 적용","applies_to":"SEOUL-EM-GREEN-2026-A01~A04","relation":"C01과 AND","source_ids":["SEOUL-EM-GREEN-2026-S01","SEOUL-EM-GREEN-2026-S02"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-GREEN-2026-C03","group":"환경교육","group_logic":"모두 충족","requirement":"환경교육 포인트는 만 14세 이상","detail":"광역센터는 서울시민, 기초센터는 해당 지역주민에게 포인트; 동일 프로그램 중복은 1회만 인정","applies_to":"SEOUL-EM-GREEN-2026-A10","relation":"C01과 AND; 연 5,000P 및 녹색실천 50,000P 한도 내","source_ids":["SEOUL-EM-GREEN-2026-S03"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-GREEN-2026-C04","group":"운전·퀴즈·이벤트","group_logic":"행동별 분기","requirement":"운전은 연계 시스템 점수, 퀴즈·행사는 각 회차 참여 조건","detail":"운전은 현대·기아 커넥티드카 안전운전 점수 85점 이상 안내; 퀴즈 1회·5회 추가 보상 등은 2026 소개 기준","applies_to":"SEOUL-EM-GREEN-2026-A05~A09","relation":"C01과 AND","source_ids":["SEOUL-EM-GREEN-2026-S01"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-GREEN-2026-C05","group":"음식물 감량 행동별 보상","group_logic":"행동별 분기","requirement":"RFID 세대 참여 확정","detail":"특별 1,000마일리지","applies_to":"SEOUL-EM-GREEN-2026-A01","relation":"C01·C02와 AND","source_ids":["SEOUL-EM-GREEN-2026-S01","SEOUL-EM-GREEN-2026-S02"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-GREEN-2026-C06","group":"음식물 감량 행동별 보상","group_logic":"행동별 분기","requirement":"전년 동기간 대비 10% 이상~20% 미만 감량","detail":"2,000마일리지","applies_to":"SEOUL-EM-GREEN-2026-A02","relation":"C01·C02와 AND","source_ids":["SEOUL-EM-GREEN-2026-S02"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-GREEN-2026-C07","group":"음식물 감량 행동별 보상","group_logic":"행동별 분기","requirement":"전년 동기간 대비 20% 이상~30% 미만 감량","detail":"3,000마일리지","applies_to":"SEOUL-EM-GREEN-2026-A03","relation":"C01·C02와 AND","source_ids":["SEOUL-EM-GREEN-2026-S02"],"verification":"공식 본문 확인"},{"id":"SEOUL-EM-GREEN-2026-C08","group":