INSERT INTO catalog_program (program_key,payload) VALUES ('district:N06','{"program_id":"N06","title":"IoT 스마트 종이팩 분리배출함","district":"성동구","target":"오늘의 분리수거 앱 또는 이즐 방식 이용 가능자","eligibility_logic":"반입 준비 AND 방문 기기의 방식(오늘의 분리수거 OR 이즐) AND 거점 운영시간·가동상태. 두 적립방식을 동시에 요구하지 않음.","benefit":"오늘의 분리수거 방식은 앱 포인트로 앱 내 상품 교환(상품 소진 시까지); 이즐 2개소는 카드·휴대폰 방식으로 보상금액 적립 표시","application_period":"장소별 운영시간 상이","usage_period":"운영기간 내 거점별 수거·교환","documents":"미확인(서류 미기재는 불필요를 뜻하지 않음)","application_method":"기기 방식에 맞춰 종이팩 바코드를 스캔하고 투입","venue":"동주민센터 17곳과 다중이용시설 10곳, 총 27개소","status":"2026 공식 본문 확인","caveat":"오늘의 분리수거 포인트 단가·이즐 보상 단가는 본문 미표시; 개별 기기 가동상태 미확인","sources":[{"id":"N06-S01","url":"https://sd.go.kr/main/contents.do?key=4490","title":"성동구 IoT 스마트 종이팩 분리배출함","status":"공식 본문 확인","as_of":"최종수정 2026-08-31","checked_at":"2026-09-17","supports":"담당 부서, 27개소·장소별 운영시간, 세척·건조·압착, 오늘의 분리수거/이즐 방식 구분"}],"overview_source_ids":["N06-S01"],"conditions":[{"id":"N06-C01","group":"배출 품목 상태","group_logic":"모두 충족","requirement":"종이팩 내용물을 비우고 세척·건조·압착","detail":"우유·두유·주스팩 등; 기기 방식별 바코드 필요","applies_to":"기기 방식에 맞춰 종이팩 바코드를 스캔하고 투입","relation":"기기 방식 조건과 모두 충족","source_ids":["N06-S01"],"verification":"공식 본문 확인"},{"id":"N06-C02","group":"오늘의 분리수거","group_logic":"모두 충족","requirement":"전용앱 설치·회원코드 태그·종이팩 바코드 태그","detail":"투입 후 앱 포인트 적립, 앱 내 상품 교환은 재고 소진 시까지","applies_to":"기기 방식에 맞춰 종이팩 바코드를 스캔하고 투입","relation":"이즐 방식과 별도","source_ids":["N06-S01"],"verification":"공식 본문 확인"},{"id":"N06-C03","group":"이즐 거점·방식","group_logic":"모두 충족","requirement":"성동아이사랑복합문화센터 또는 서울숲복합문화체육센터의 이즐 기기","detail":"이즐 카드/휴대폰과 바코드 스캔 후 투입; 화면상 보상금액 확인","applies_to":"기기 방식에 맞춰 종이팩 바코드를 스캔하고 투입","relation":"오늘의 분리수거와 별도","source_ids":["N06-S01"],"verification":"공식 본문 확인"},{"id":"N06-C04","group":"운영 상태","group_logic":"제한","requirement":"27개 설치거점의 운영시간 확인","detail":"기기 점검 중 또는 수거함 Full이면 사용 불가","applies_to":"기기 방식에 맞춰 종이팩 바코드를 스캔하고 투입","relation":"앞 조건 충족해도 적용","source_ids":["N06-S01"],"verification":"공식 본문 확인"}],"display_title":"[성동구] IoT 스마트 종이팩 분리배출함"}'::jsonb);
