INSERT INTO catalog_program (program_key,payload) VALUES ('district:N04','{"program_id":"N04","title":"다시 쓰는 청구 장바구니","district":"중구","target":"주민 100명","eligibility_logic":"주민 100명. 페트병·종이팩·건전지·캔·유리병 60개 또는 우유팩·비닐 3kg은 쿠폰 1회 기준이며, 하루 1쿠폰; 10쿠폰 달성 시 장바구니.","benefit":"10회 쿠폰 달성 시 장바구니","application_period":"2026년 7~12월 매주 목요일 09:00~12:00; 소진 시 조기 종료","usage_period":"운영기간 내 거점별 수거·교환","documents":"미확인(서류 미기재는 불필요를 뜻하지 않음)","application_method":"정해진 수량의 페트병·종이팩·건전지·캔·유리병·우유팩·비닐을 가져와 쿠폰을 모아 장바구니 받기","venue":"청구동주민센터 1층 우측 입구","status":"기간 명시된 동 특화사업","caveat":"9월 17일 잔여 장바구니 수량","sources":[{"id":"N04-S01","url":"https://www.junggu.seoul.kr/dong/cheonggu/content.do?cid=1459196778&cmsid=13327&mode=view","title":"청구동 다시 쓰는 청구 장바구니 사업","status":"기존 자료만","as_of":"2026-07-07","checked_at":"2026-09-17","supports":"대상·장소·기간·교환 조건·보상"}],"overview_source_ids":["N04-S01"],"conditions":[{"id":"N04-C01","group":"참여 대상","group_logic":"묶음 안 하나 충족","requirement":"주민 100명","detail":"입력 후보에 기재된 대상; 지자체 주소만으로 주민자격을 추가 추정하지 않음","applies_to":"정해진 수량의 페트병·종이팩·건전지·캔·유리병·우유팩·비닐을 가져와 쿠폰을 모아 장바구니 받기","relation":"아래 품목·수량·회차 조건과 함께 적용","source_ids":["N04-S01"],"verification":"공식 검색결과만 확인"},{"id":"N04-C02","group":"세부 조건","group_logic":"대체 수량 기준(OR)","requirement":"각 페트병·종이팩·건전지·캔·유리병 60개당 1회","detail":"입력에 기록된 개별 요건","applies_to":"정해진 수량의 페트병·종이팩·건전지·캔·유리병·우유팩·비닐을 가져와 쿠폰을 모아 장바구니 받기","relation":"C03과 대체되는 쿠폰 1회 수량 기준; C04 일일 한도 적용","source_ids":["N04-S01"],"verification":"공식 검색결과만 확인"},{"id":"N04-C03","group":"세부 조건","group_logic":"대체 수량 기준(OR)","requirement":"우유팩·비닐 3kg당 1회","detail":"입력에 기록된 개별 요건","applies_to":"정해진 수량의 페트병·종이팩·건전지·캔·유리병·우유팩·비닐을 가져와 쿠폰을 모아 장바구니 받기","relation":"C02와 대체되는 쿠폰 1회 수량 기준; C04 일일 한도 적용","source_ids":["N04-S01"],"verification":"공식 검색결과만 확인"},{"id":"N04-C04","group":"세부 조건","group_logic":"모두 충족","requirement":"하루 1쿠폰","detail":"입력에 기록된 개별 요건","applies_to":"정해진 수량의 페트병·종이팩·건전지·캔·유리병·우유팩·비닐을 가져와 쿠폰을 모아 장바구니 받기","relation":"다른 세부 조건과 함께 적용; 회차·거점별 상이는 별도 확인","source_ids":[